        "autorImagen": "https://i.pravatar.cc/150?u=javiersolis",
        "contenidoCompleto": `
            <h2>El Cóctel que Enciende la Noche</h2>
            <p>Eleva tus reuniones con este cóctel vibrante y delicioso. El "Fuego de Dragón" es fácil de preparar y su color fucsia natural dejará a todos impresionados.</p>
            <h3>Ingredientes:</h3>
            <p>2 oz de Pisco Quebranta, 1 oz de zumo de pitahaya fresca (pulpa licuada y colada), 3/4 oz de zumo de limón fresco, 1/2 oz de jarabe de goma, hojas de menta y hielo.</p>
            <h3>Preparación:</h3>
            <p>En una coctelera, añade el pisco, el zumo de pitahaya, el zumo de limón y el jarabe de goma. Agrega hielo y agita enérgicamente durante 15 segundos. Sirve en un vaso corto con hielo fresco y decora con una rodaja fina de pitahaya y unas hojas de menta. ¡Salud!</p>
        `
