        "contenidoCompleto": `
            <h2>The Cocktail That Ignites the Night</h2>
            <p>Elevate your gatherings with this vibrant and delicious cocktail. The "Dragon's Fire" is easy to prepare and its natural fuchsia color will impress everyone.</p>
            <h3>Ingredients:</h3>
            <ul>
                <li>2 oz of Pisco Quebranta</li>
                <li>1 oz of fresh pitahaya juice (blended and strained pulp)</li>
                <li>3/4 oz of fresh lime juice</li>
                <li>1/2 oz of simple syrup</li>
                <li>Mint or spearmint leaves</li>
                <li>Ice</li>
            </ul>
            <h3>Preparation:</h3>
            <p>In a shaker, add the pisco, pitahaya juice, lime juice, and simple syrup. Add ice and shake vigorously for 15 seconds. Serve in a short glass with fresh ice and garnish with a thin slice of pitahaya and some mint leaves. Cheers!</p>
        `
