        "contenidoCompleto": `
            <h2>Le Cocktail qui Enflamme la Nuit</h2>
            <p>Rehaussez vos réunions avec ce cocktail vibrant et délicieux. Le "Feu du Dragon" est facile à préparer et sa couleur fuchsia naturelle impressionnera tout le monde.</p>
            <h3>Ingrédients :</h3>
            <p>2 oz de Pisco Quebranta, 1 oz de jus de pitaya frais (pulpe mixée et filtrée), 3/4 oz de jus de citron frais, 1/2 oz de sirop de gomme, feuilles de menthe et glaçons.</p>
            <h3>Préparation :</h3>
            <p>Dans un shaker, ajoutez le pisco, le jus de pitaya, le jus de citron et le sirop de gomme. Ajoutez des glaçons et secouez énergiquement pendant 15 secondes. Servez dans un verre court avec des glaçons frais et décorez avec une fine tranche de pitaya et quelques feuilles de menthe. Santé !</p>
        `
