            <p>Scalda le tortillas di mais, disponi sopra i pezzi di pesce alla griglia, aggiungi un cucchiaio generoso di salsa alla pitaya e completa con del cavolo viola tagliato finemente per dare un tocco croccante. Un'esplosione di sapori tropicali in ogni boccone!</p>
